def largest_island(grid):
    n = len(grid)
    areas = {}
    island_id = 2

    def dfs(r, c, island_id):
        if r < 0 or r >= n or c < 0 or c >= n or grid[r][c] != 1:
            return 0
        grid[r][c] = island_id
        return 1 + dfs(r + 1, c, island_id) + dfs(r - 1, c, island_id) + dfs(r, c + 1, island_id) + dfs(r, c - 1, island_id)

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                areas[island_id] = dfs(r, c, island_id)
                island_id += 1

    best = max(areas.values()) if areas else 0

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                neighbor_ids = set()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] != 0:
                        neighbor_ids.add(grid[nr][nc])
                total = 1 + sum(areas[i] for i in neighbor_ids)
                best = max(best, total)

    return best

